def transform(grid):
    out = [row[:] for row in grid]
    # The two markers outside the frame color opposite 2x2 quadrants.
    a, b = grid[8][1], grid[8][8]
    for r in range(3, 7):
        for c in range(3, 7):
            out[r][c] = a if ((r < 5) == (c < 5)) else b
    return out
